        String title,
        UUID requesterUserId,
        UUID assigneeUserId,
        UUID targetDefinitionId,
        UUID targetRunId,
        UUID targetRecipeVersionId,
        Map<String, Object> proposedPayload,
        String proposedPayloadJson,
        String idempotencyKey
) {

    public SapPostingTicketCreateCommand {
        Objects.requireNonNull(title, "title must not be null");
        Objects.requireNonNull(requesterUserId, "requesterUserId must not be null");
        Objects.requireNonNull(targetDefinitionId, "targetDefinitionId must not be null");
        Objects.requireNonNull(targetRunId, "targetRunId must not be null");
        Objects.requireNonNull(targetRecipeVersionId, "targetRecipeVersionId must not be null");
        proposedPayload = proposedPayload == null ? Map.of() : Map.copyOf(proposedPayload);
        Objects.requireNonNull(proposedPayloadJson, "proposedPayloadJson must not be null");
        Objects.requireNonNull(idempotencyKey, "idempotencyKey must not be null");
    }
}
