        String fingerprint = sha256Hex(runId + "|" + request.ticketId() + "|" + reason + "|" + request.version());
        if (idempotencyKeyHeader != null && !idempotencyKeyHeader.isBlank()) {
            String idemKey = ContractGuards.requireIdempotencyKey(idempotencyKeyHeader);
            if (checkIdempotentReplay("approve-sap:" + runId, idemKey, fingerprint).isPresent()) {
                return orchestratorService.getReportRunById(runId);
            }
        }
        ReportRunEntity run = reportRunRepository.findById(runId)
                .orElseThrow(() -> ContractProblemException.notFound("Report run not found: " + runId));
        requireRunOptimisticVersion(ifMatchHeader, request.version(), run.version());
        if (!"SUCCESS".equals(run.status())) {
            throw ContractProblemException.concurrencyConflict(
                    HttpStatus.CONFLICT, "Only SUCCESS report runs can be approved for SAP posting: " + runId);
        }
        executeSapApprovalAndBumpVersion(run, request.ticketId(), reason, principal, correlationId, clientIp);
        if (idempotencyKeyHeader != null && !idempotencyKeyHeader.isBlank()) {
            storeIdempotentResult("approve-sap:" + runId, idempotencyKeyHeader.trim(), fingerprint, runId);
        }
        return orchestratorService.getReportRunById(runId);
    }"

